class Solution:
    def maxWeightNode(self, edge: List[int]) -> int:
        n = len(edge); w = [0] * n
        for i, x in enumerate(edge):
            if x != -1: w[x] += i
        m = max(w)
        return max(i for i in range(n) if w[i] == m)

